"""Qualified Rust MCP -> direct SSH -> original owner recovery on Linux.

Run on the same X230 reached by the explicitly supplied SSH alias. All effects,
controller state and remote job state are confined to one fresh directory. The
three fixed cases cover controller loss, a launch reply not consumed by the
client, and original-owner loss after one synthetic durable effect. No pool
profile, production controller, service restart or host reboot is involved.
"""
from __future__ import annotations

import argparse
import ctypes
import hashlib
import json
import os
from pathlib import Path
import re
import select
import shlex
import signal
import socket
import stat
import subprocess
import sys
import time

DEV = Path("/home/qian/hepta-runtime-optimization-20261023/a41-phase-timing-20261025-r01")
CASES = ("controller-loss", "reply-loss", "owner-loss")
MAX_MESSAGE = 1024 * 1024
INPUT = ("0123456789abcdef" * 256).encode()
EFFECT = b"EXECUTED\n"
RELEASE = b"RELEASE\n"
CHILD = r'''import hashlib,json,os,pathlib,sys,time
data=sys.stdin.buffer.read()
