def need(condition, message):
    if not condition:
        raise RuntimeError(message)


def canonical(value):
    return (json.dumps(value, sort_keys=True, indent=2) + "\n").encode()


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def stamp(info):
    return (info.st_dev, info.st_ino, info.st_uid, info.st_mode, info.st_nlink,
            info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def direct(path):
    path = Path(path).absolute()
    need(path == path.resolve(strict=True), "path traverses a symlink: " + str(path))
    return path


def read(path, limit=MAX_MESSAGE):
    path = direct(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK)
    try:
        before = os.fstat(fd)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink == 1
             and before.st_size <= limit, "unsafe/oversized input: " + str(path))
        chunks, size = [], 0
        while True:
            chunk = os.read(fd, min(65536, limit + 1 - size))
            if not chunk:
                break
            size += len(chunk)
            need(size <= limit, "input grew beyond limit")
            chunks.append(chunk)
        need(stamp(before) == stamp(os.fstat(fd)) == stamp(path.stat()),
             "input changed during read: " + str(path))
        return b"".join(chunks)
    finally:
        os.close(fd)


def file_receipt(path):
    path = direct(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink == 1, "unsafe file")
        value = hashlib.sha256()
        while True:
            block = os.read(fd, 1024 * 1024)
            if not block:
                break
            value.update(block)
        need(stamp(before) == stamp(os.fstat(fd)) == stamp(path.stat()), "file changed")
        return {"path": str(path), "sha256": value.hexdigest(), "bytes": before.st_size,
                "identity": list(stamp(before))}
    finally:
        os.close(fd)


def create(path, raw, mode=0o600):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def save(path, value):
    pending = path.with_name(path.name + ".pending")
    create(pending, canonical(value))
    os.replace(pending, path)
    directory_sync(path.parent)


def directory_sync(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def validate_ssh_config(path):
    # A single pinned admission file must describe the connection completely.
    # Included configuration or executable match/proxy rules need a separately
    # admitted profile and are intentionally outside this same-host fixture.
    for number, line in enumerate(read(path, 64 * 1024).decode().splitlines(), 1):
        fields = shlex.split(line, comments=True)
        if not fields:
            continue
        keyword, separator, inline = fields[0].partition("=")
        keyword = keyword.lower()
        values = ([inline] if separator else []) + fields[1:]
        need(keyword not in ("include", "match"), "SSH admission must be flattened at line " + str(number))
        if keyword in ("proxycommand", "proxyjump"):
            need(values == ["none"], "SSH admission must connect directly at line " + str(number))


def process_identity(pid):
    fields = Path(f"/proc/{pid}/stat").read_text().rsplit(") ", 1)[1].split()
    return {"pid": pid, "birth_ticks": int(fields[19]), "state": fields[0],
            "ppid": int(fields[1]), "pgid": int(fields[2]), "sid": int(fields[3]),
            "uid": Path(f"/proc/{pid}").stat().st_uid,
            "boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip()}


def same_process(before):
    try:
        current = process_identity(before["pid"])
        return all(current[key] == before[key] for key in ("pid", "birth_ticks", "uid", "boot_id"))
    except (FileNotFoundError, ProcessLookupError):
        return False


def own_child_pids():
    """Only this harness's direct children; no host inventory is retained."""
    return [int(v) for v in Path(f"/proc/{os.getpid()}/task/{os.getpid()}/children").read_text().split()]


def bound_pidfd(identity):
    need(same_process(identity), "process incarnation changed before pidfd open")
    fd = os.pidfd_open(identity["pid"], 0)
    try:
        need(same_process(identity), "process incarnation changed after pidfd open")
    except BaseException:
        os.close(fd)
        raise
    return fd


def pidfd_exited(fd, timeout=0):
    return bool(select.select([fd], [], [], timeout)[0])


def signal_bound(fd, identity, number):
    need(not pidfd_exited(fd) and same_process(identity), "bound original process is not live")
    signal.pidfd_send_signal(fd, number)
    return {"signal": signal.Signals(number).name, "identity": identity,
            "submitted_monotonic_ns": time.monotonic_ns(), "pidfd_bound": True}


class Controller:
    """Sequential JSON-RPC client; reply-loss deliberately performs no stdout read."""

    def __init__(self, binary, config, directory, wrapper_dir):
        directory.mkdir(mode=0o700)
        self.directory, self.serial = directory, 0
        self.buffer, self.eof, self.reaped = bytearray(), False, False
        self.cleanup_complete, self.cleanup_deadline = False, None
        self.raw = open(directory / "stdout.original.jsonl", "xb", buffering=0)
        self.err = open(directory / "stderr.original.log", "xb", buffering=0)
        self.requests = open(directory / "requests.original.jsonl", "xb", buffering=0)
        self.argv = [str(binary), "mcp", "--runtime-config", str(config),
                     "--runtime-prewarm", "--runtime-audit-group-commit"]
        env = dict(os.environ, PATH=str(wrapper_dir) + ":/usr/bin:/bin",
                   TOKIO_WORKER_THREADS="2", RUST_LOG="warn")
        self.child = subprocess.Popen(self.argv, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                      stderr=self.err, cwd=directory, env=env, start_new_session=True)
        # The unreaped original Popen child pins this PID even if a later
        # /proc identity read fails. Acquire the kernel handle immediately.
        self.pidfd = None
        try:
            self.pidfd = os.pidfd_open(self.child.pid, 0)
            self.identity = process_identity(self.child.pid)
            need(same_process(self.identity), "controller identity unavailable")
            os.set_blocking(self.child.stdout.fileno(), False)
        except BaseException as initial_error:
            cleanup = {"error": type(initial_error).__name__ + ": " + str(initial_error),
                       "original_child_pid": self.child.pid, "original_wait4": None}
            try:
                # No wait/poll has reaped this original child. Its PID cannot
                # be recycled; this fallback never accepts a caller's PID.
                if self.pidfd is not None:
                    if not pidfd_exited(self.pidfd):
                        signal.pidfd_send_signal(self.pidfd, signal.SIGKILL)
                else:
                    try:
                        os.kill(self.child.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                deadline = time.monotonic() + 5
                while True:
                    waited, status, _ = os.wait4(self.child.pid, os.WNOHANG)
                    if waited == self.child.pid:
                        self.child.returncode = os.waitstatus_to_exitcode(status)
                        cleanup["original_wait4"] = {"pid": waited, "raw_status": status,
                                                     "exit_code": self.child.returncode}
                        break
                    need(waited == 0 and time.monotonic() < deadline, "initial controller cleanup did not reap")
                    time.sleep(.01)
            except BaseException as error:
                cleanup["cleanup_error"] = type(error).__name__ + ": " + str(error)
            finally:
                if self.pidfd is not None:
                    os.close(self.pidfd)
                for stream in (self.child.stdin, self.child.stdout, self.raw, self.err, self.requests):
                    try:
                        stream.close()
                    except BaseException:
                        pass
                save(directory / "startup-failure.json", cleanup)
            raise
        self.result = {"argv": self.argv, "identity": self.identity, "signals": [],
                       "original_wait4": None, "stdout_eof": False, "adopted_children": []}
        try:
            reply = self.rpc("initialize", {"protocolVersion": "2025-03-26", "capabilities": {},
                             "clientInfo": {"name": "hepta-native-owner-recovery", "version": "1"}}, 30)
            need("result" in reply and "error" not in reply, "MCP initialize failed")
            self.send("notifications/initialized", {}, notification=True)
            self.result["server_info"] = reply["result"].get("serverInfo")
        except BaseException:
            self.stop()
            raise

    def send(self, method, params, notification=False):
        request = {"jsonrpc": "2.0", "method": method, "params": params}
        if not notification:
            self.serial += 1
            request["id"] = self.serial
        raw = json.dumps(request, separators=(",", ":")).encode() + b"\n"
        need(len(raw) <= MAX_MESSAGE, "oversized request")
        self.requests.write(raw)
        self.child.stdin.write(raw)
        self.child.stdin.flush()
        return request.get("id")

    def pump(self, timeout):
        if self.eof:
            return
        if select.select([self.child.stdout], [], [], timeout)[0]:
            block = os.read(self.child.stdout.fileno(), 65536)
            if not block:
                self.eof = True
                return
            self.raw.write(block)
            self.buffer.extend(block)
            need(len(self.buffer) <= MAX_MESSAGE, "MCP response exceeds bound")

    def response(self, identity, timeout=30):
        deadline = time.monotonic() + timeout
        while True:
            while b"\n" in self.buffer:
                line, _, tail = self.buffer.partition(b"\n")
                self.buffer = bytearray(tail)
                value = json.loads(line)
                if "id" not in value:
                    continue
                need(value["id"] == identity, "unexpected response identity")
                return value
            need(not self.eof and time.monotonic() < deadline, "MCP response unavailable")
            self.pump(min(.1, deadline - time.monotonic()))

    def rpc(self, method, params, timeout=30):
        return self.response(self.send(method, params), timeout)

    def call(self, tool, arguments):
        need(tool in ("process_start", "process_status", "process_read"), "unplanned tool")
        reply = self.rpc("tools/call", {"name": tool, "arguments": arguments})
        need("error" not in reply and not reply.get("result", {}).get("isError"),
             "native call failed: " + json.dumps(reply))
        texts = [item["text"] for item in reply["result"].get("content", []) if item.get("type") == "text"]
        need(texts, "native result missing")
        value = json.loads(texts[0])
        need(value.get("audit_recorded") is True and "audit_warning" not in value,
             "native operation lacks durable audit acknowledgement")
        return value

    def stop(self, crash=False):
        if self.cleanup_complete:
            return self.result
        if self.cleanup_deadline is None:
            self.cleanup_deadline = time.monotonic() + 60
        errors = self.result.setdefault("cleanup_errors", [])

        def failed(scope, error):
            errors.append(scope + ": " + type(error).__name__ + ": " + str(error))

        def pump_safely():
            if self.child.stdout.closed:
                return
            try:
                self.pump(.05)
            except BaseException as error:
                failed("stdout capture", error)
                # A failed diagnostic sink must not prevent original-child
                # cleanup. Retain failure and drain without claiming capture.
                self.buffer.clear()
                try:
                    if select.select([self.child.stdout], [], [], .05)[0]:
                        if not os.read(self.child.stdout.fileno(), 65536):
                            self.eof = True
                except BaseException as drain_error:
                    failed("stdout drain", drain_error)
                    time.sleep(.05)

        if not self.reaped:
            self.result.setdefault("shutdown", "intentional_controller_sigkill" if crash else "stdin_eof")
            if crash:
                try:
                    self.result["signals"].append(signal_bound(self.pidfd, self.identity, signal.SIGKILL))
                except BaseException as error:
                    failed("intentional controller signal", error)
            try:
                if not self.child.stdin.closed:
                    self.child.stdin.close()
            except BaseException as error:
                failed("stdin close", error)
            deadline = min(self.cleanup_deadline, time.monotonic() + (10 if crash else 30))
            while not pidfd_exited(self.pidfd) and time.monotonic() < deadline:
                pump_safely()
            for number in (signal.SIGTERM, signal.SIGKILL):
                if pidfd_exited(self.pidfd):
                    break
                self.result["shutdown"] = "cleanup_signal_required"
                try:
                    self.result["signals"].append(signal_bound(self.pidfd, self.identity, number))
                except BaseException as error:
                    failed("controller cleanup signal", error)
                end = min(self.cleanup_deadline, time.monotonic() + 5)
                while not pidfd_exited(self.pidfd) and time.monotonic() < end:
                    pump_safely()
            try:
                need(pidfd_exited(self.pidfd), "original controller did not exit")
                waited, raw_status, usage = os.wait4(self.child.pid, os.WNOHANG)
                need(waited == self.child.pid, "original controller wait4 identity differs")
                self.child.returncode = os.waitstatus_to_exitcode(raw_status)
                self.result["original_wait4"] = {"pid": waited, "raw_status": raw_status,
                    "exit_code": self.child.returncode, "user_seconds": usage.ru_utime,
                    "system_seconds": usage.ru_stime, "maxrss_kib": usage.ru_maxrss}
                self.reaped = True
            except BaseException as error:
                failed("original wait4", error)
        end = min(self.cleanup_deadline, time.monotonic() + 5)
        while not self.eof and not self.child.stdout.closed and time.monotonic() < end:
            pump_safely()
        self.result["stdout_eof"] = self.eof
        self.result["unconsumed_reply_bytes"] = len(self.buffer)
        for stream in (self.child.stdout, self.raw, self.err, self.requests):
            if stream.closed:
                continue
            try:
                stream.flush()
                if stream in (self.raw, self.err, self.requests):
                    os.fsync(stream.fileno())
            except BaseException as error:
                failed("stream sync", error)
            finally:
                try:
                    stream.close()
                except BaseException as error:
                    failed("stream close", error)
        # Subreaper adoption applies only after the original controller exits.
        # Never count its pidfd readability as an actual wait4/reap receipt.
        known = {}
        settled = False
        if self.reaped:
            end = min(self.cleanup_deadline - 5, time.monotonic() + 10)
            try:
                while True:
                    children = own_child_pids()
                    if not children:
                        settled = True
                        break
                    for pid in children:
                        if pid not in known:
                            identity = process_identity(pid)
                            need(identity["ppid"] == os.getpid(), "adopted child ownership changed")
                            known[pid] = {"identity": identity, "pidfd": bound_pidfd(identity), "signals": []}
                        row = known[pid]
                        if not pidfd_exited(row["pidfd"]) and time.monotonic() >= end:
                            row["signals"].append(signal_bound(row["pidfd"], row["identity"], signal.SIGKILL))
                        if pidfd_exited(row["pidfd"]):
                            waited, status, _ = os.wait4(pid, os.WNOHANG)
                            need(waited == pid, "adopted child wait identity differs")
                            os.close(row.pop("pidfd"))
                            row.update(raw_wait_status=status, exit_code=os.waitstatus_to_exitcode(status))
                            self.result["adopted_children"].append(row)
                            del known[pid]
                    need(time.monotonic() < self.cleanup_deadline, "owned adopted children remain")
                    time.sleep(.05)
            except BaseException as error:
                failed("adopted SSH cleanup", error)
            finally:
                for row in known.values():
                    if "pidfd" in row:
                        os.close(row.pop("pidfd"))
        if self.reaped and self.pidfd is not None:
            os.close(self.pidfd)
            self.pidfd = None
        self.cleanup_complete = self.reaped and settled
        self.result["cleanup_complete"] = self.cleanup_complete
        save(self.directory / "controller-receipt.json", self.result)
        return self.result


def qualification(path, expected_sha256):
    original = read(path)
    need(digest(original) == expected_sha256, "qualification receipt differs from pinned input")
    q = json.loads(original)
    need(q.get("schema") == "runtime-candidate-qualification/v1" and q.get("qualified") is True
         and q.get("current_stage") == "complete" and not q.get("error"), "qualification is not complete")
    tested = q["source_tested"]
    need(tested and tested == q["source_after"], "qualified source map differs")
    source = direct(q["source"])
    actual = {str(p.relative_to(source)): file_receipt(p)["sha256"]
              for p in sorted(source.rglob("*")) if p.is_file()}
    need(actual == tested, "actual source differs from tested source")
    stages = {row["name"]: row for row in q["stages"]}
    need(len(stages) == len(q["stages"]) and {"fmt-check", "clippy", "test", "release"} <= set(stages)
         and all(row["returncode"] == 0 for row in stages.values()), "qualification stages differ")
    binary = file_receipt(q["binary"]["path"])
    need(q["binary"].get("cached") is False and binary["sha256"] == q["binary"]["sha256"],
         "qualified release changed or was reused")
    release = read(path.parent / "release.log", 32 * 1024 * 1024)
    need(digest(release) == stages["release"]["log_sha256"], "release compiler log changed")
    events = []
    for line in release.splitlines():
        try:
            row = json.loads(line)
        except (ValueError, UnicodeDecodeError):
            continue
        if isinstance(row, dict) and row.get("reason") == "compiler-artifact" and row.get("target", {}).get("name") == "hepta-runtime" and row.get("profile", {}).get("test") is False:
            events.append(row)
    need(len(events) == 1 and events[0].get("fresh") is False
         and events[0].get("manifest_path") == str(source / "Cargo.toml")
         and events[0]["target"].get("src_path") == q["binary"]["compiler_source"],
         "release compiler provenance differs")
    return q, {"qualification": file_receipt(path), "binary": binary,
               "source": str(source), "source_files": len(actual),
               "source_map_sha256": digest(canonical(actual)), "source_map": actual}


def until(check, seconds, message):
    deadline = time.monotonic() + seconds
    while True:
        value = check()
        if value:
            return value
        need(time.monotonic() < deadline, message)
        time.sleep(.05)


def load_job(state, request):
    matches = []
    for path in (state / "jobs").glob("*.json"):
        row = json.loads(read(path))
        if row.get("idempotency_key") == request["idempotency_key"]:
            matches.append(row)
    need(len(matches) == 1, "same-key durable identity is absent or ambiguous")
    return matches[0]


def verify_job(record, root, request):
    need(record.get("host") == "x230" and record.get("execution_mode") == "operator"
         and record.get("system_jobctl") is False
         and record.get("idempotency_key") == request["idempotency_key"]
         and record.get("executable") == request["executable"] and record.get("args") == request["args"],
         "job binding differs")
    job = root / "target-state" / "jobs" / record["id"]
    need(record["remote_job_dir"] == str(job) and direct(job) == job,
         "remote fixture directory escaped the new root")
    req = json.loads(read(job / "request.json"))
    started = json.loads(read(job / "started.json"))
    need(req.get("job_id") == record["id"] and req.get("request_fingerprint") == record["request_digest"]
         and started.get("job_id") == record["id"] and started.get("launch_nonce") == req.get("launch_nonce"),
         "original remote owner does not bind original request")
    return job, req, started


def case(name, root, binary, wrapper_dir, ssh_target, report):
    root.mkdir(mode=0o700)
    for path in (root / "state", root / "state/jobs", root / "target-state"):
        path.mkdir(mode=0o700)
    cfg = {"state_dir": str(root / "state"), "controller_workspace_roots": [], "hosts": {"x230": {
        "ssh_target": ssh_target, "platform": "linux", "execution_mode": "operator",
        "remote_state_dir": str(root / "target-state"), "allow_execute": True,
        "allow_pty": False, "allow_write": False, "allow_job_network": True,
        "allow_detached_fallback": False, "privileged_actions": {}}}}
    create(root / "runtime.json", canonical(cfg))
    request = {"host": "x230", "executable": "/usr/bin/python3", "args": ["-I", "-S", "-u", "-c", CHILD,
        str(root / "effect"), digest(INPUT), str(root / "release")], "cwd": str(root), "env": {},
        "stdin": INPUT.decode(), "timeout_seconds": 90,
        "idempotency_key": "native-owner-" + digest(str(root).encode())[:24]}
    create(root / "request.original.json", canonical(request))
    report.update(name=name, passed=False, started_monotonic_ns=time.monotonic_ns(), calls=[],
                  start_requests=0, actual_business_starts_expected=1)
    controller = None
    owner_fd = child_fd = None
    try:
        controller = Controller(binary, root / "runtime.json", root / "controller-0", wrapper_dir)
        report["start_requests"] += 1
        if name == "reply-loss":
            report["unconsumed_launch_rpc_id"] = controller.send("tools/call", {"name": "process_start", "arguments": request})
            report["launch_reply_consumed_before_controller_kill"] = False
        else:
            first = controller.call("process_start", request)
            report["first_launch"] = first
            need(first.get("reused") is False and first.get("launch", {}).get("backend") == "systemd",
                 "first launch not new systemd-owned job")
        until(lambda: read(root / "effect.ready") == b"READY\n" if (root / "effect.ready").exists() else False,
              20, "durable business effect readiness never appeared")
        need(read(root / "effect") == EFFECT, "business already repeated")
        record = load_job(root / "state", request)
        job, req, started = verify_job(record, root, request)
        report["original_record"] = record
        report["remote_owner_binding"] = started
        owner = process_identity(started["supervisor_pid"])
        need(started["supervisor_uid"] == owner["uid"] == os.geteuid()
             and started["supervisor_identity"] == {"kind": "proc_start_ticks", "value": owner["boot_id"] + ":" + str(owner["birth_ticks"])},
             "original supervisor incarnation differs")
        owner_fd = bound_pidfd(owner)
        child_receipt = until(lambda: json.loads(read(job / "child.json")) if (job / "child.json").exists() else None,
                              5, "original child receipt missing")
        child = process_identity(child_receipt["pid"])
        need(child_receipt.get("identity") == {"kind": "proc_start_ticks", "value": child["boot_id"] + ":" + str(child["birth_ticks"])}
             and child["ppid"] == owner["pid"] and child["uid"] == owner["uid"], "original business child binding differs")
        child_fd = bound_pidfd(child)
        reference = {"host": "x230", "job_id": record["id"]}
        if name == "owner-loss":
            need(not pidfd_exited(child_fd), "business already exited before owner-loss injection")
            report["intentional_owner_signal"] = signal_bound(owner_fd, owner, signal.SIGKILL)
            need(pidfd_exited(owner_fd, 10), "original owner did not exit")
            # systemd KillMode=control-group owns this cleanup. The harness
            # neither invents an outcome nor signals a potentially reused PID.
            need(pidfd_exited(child_fd, 15), "original systemd unit did not stop the business child")
            report["owner_and_business_pidfds_exited"] = True
        else:
            report["controller_crash"] = controller.stop(crash=True)
            need(report["controller_crash"]["original_wait4"]["exit_code"] == -signal.SIGKILL
                 and report["controller_crash"]["stdout_eof"]
                 and report["controller_crash"]["cleanup_complete"]
                 and not report["controller_crash"]["cleanup_errors"], "controller crash/reap differs")
            controller = None
            need(not pidfd_exited(owner_fd) and not pidfd_exited(child_fd), "original owner/business did not survive controller loss")
            controller = Controller(binary, root / "runtime.json", root / "controller-1", wrapper_dir)
        status = controller.call("process_status", reference)
        report["first_recovered_status"] = status
        need(status.get("job_id") == record["id"], "recovered status job identity differs")
        if name == "owner-loss":
            need(status.get("state") in ("finalizing", "owner_unknown")
                 and status.get("status_authoritative") is False and status.get("automatic_retry") is False
                 and status.get("terminal_publication_confirmed") is not True,
                 "owner loss was not reported as unconfirmed/unknown")
        else:
            need(status.get("state") == "running", "original business not running after controller restart")
        preserved_paths = [root / "state/jobs" / (record["id"] + ".json")]
        preserved_paths.extend(job / filename for filename in ("request.json", "owner-intent.json", "started.json", "child.json", "runner.py"))
        report["before_same_key_original_files"] = [file_receipt(path) for path in preserved_paths]
        report["start_requests"] += 1
        reused = controller.call("process_start", request)
        report["same_key_reuse"] = reused
        need(reused.get("reused") is True and reused.get("retried_launch") is False
             and reused.get("launch") is None and reused.get("job", {}).get("id") == record["id"],
             "same key relaunched or changed original identity")
        need(reused.get("status", {}).get("job_id") == record["id"], "same-key status job identity differs")
        need(read(root / "effect") == EFFECT, "synthetic effect repeated during reconciliation")
        report["after_same_key_original_files"] = [file_receipt(path) for path in preserved_paths]
        need(report["before_same_key_original_files"] == report["after_same_key_original_files"],
             "same-key reconciliation modified original job/owner identities")
        if name == "owner-loss":
            need(reused.get("status", {}).get("automatic_retry") is False
                 and reused["status"].get("status_authoritative") is False, "same-key status invented certainty")
            need(not (job / "exit.witness.json").exists(), "unexpected confirmed terminal after original owner kill")
        else:
            create(root / "release", RELEASE)
            directory_sync(root)
            deadline = time.monotonic() + 30
            while True:
                terminal = controller.call("process_status", reference)
                report["calls"].append({"tool": "process_status", "value": terminal})
                need(terminal.get("job_id") == record["id"], "terminal status job identity differs")
                if terminal.get("state") == "succeeded":
                    break
                need(time.monotonic() < deadline and terminal.get("state") in ("running", "activating", "finalizing"),
                     "original job failed to reach terminal")
                time.sleep(.2)
            exit_raw = read(job / "exit.json")
            exit_value = json.loads(exit_raw)
            witness = json.loads(read(job / "exit.witness.json"))
            need(terminal.get("terminal_publication_confirmed") is True and terminal.get("exit_code") == 0
                 and terminal.get("output_complete") is True and terminal.get("output_durable") is True
                 and terminal.get("automatic_retry") is False
                 and all(terminal.get(k) == v for k, v in exit_value.items()), "native terminal differs from original durable receipt")
            for value in (req, exit_value, witness):
                need(type(value.get("terminal_publication_protocol")) is int and value["terminal_publication_protocol"] == 1
                     and value.get("job_id") == record["id"] and value.get("launch_nonce") == req["launch_nonce"],
                     "terminal publication identities differ")
            need(witness.get("exit_sha256") == digest(exit_raw), "witness does not bind exact exit bytes")
            output = controller.call("process_read", {**reference, "stdout_offset": 0, "stderr_offset": 0, "limit": 16384})
            expected = {"stdout": ("BEGIN\nEND " + digest(INPUT) + "\n").encode(), "stderr": b"RECOVERY-STDERR\n"}
            for stream, raw in expected.items():
                part = output[stream]
                need(bytes.fromhex(part["bytes_hex"]) == raw and read(job / (stream + ".log")) == raw
                     and part["offset"] == 0 and part["next_offset"] == part["size"] == len(raw)
                     and part["eof"] is True, "complete output or byte cursors differ")
            need(read(job / "stdin.bin") == INPUT, "durable stdin changed")
            need(pidfd_exited(owner_fd, 10) and pidfd_exited(child_fd), "original job processes did not finish")
            report.update(terminal=terminal, witness=witness, output=output)
        need(load_job(root / "state", request)["id"] == record["id"] and read(root / "effect") == EFFECT,
             "identity or effect changed at final check")
        report["shutdown"] = controller.stop()
        need(report["shutdown"]["shutdown"] == "stdin_eof" and report["shutdown"]["original_wait4"]["exit_code"] == 0
             and report["shutdown"]["stdout_eof"] and report["shutdown"]["cleanup_complete"]
             and not report["shutdown"]["cleanup_errors"], "normal controller shutdown failed")
        need(not report["shutdown"]["adopted_children"], "normal shutdown orphaned a child")
        controller = None
        report.update(passed=True, business_effect_count=1, same_job_identity_preserved=True)
    finally:
        # An error must not strand the one bounded fixture business. Releasing
        # it cannot submit new work and lets the original owner publish status.
        try:
            if not (root / "release").exists():
                create(root / "release", RELEASE)
                directory_sync(root)
                report["cleanup_release_published"] = True
            else:
                need(read(root / "release") == RELEASE, "fixture release marker changed")
        except BaseException as error:
            report["cleanup_release_error"] = type(error).__name__ + ": " + str(error)
            report["passed"] = False
        if controller is not None:
            try:
                report["cleanup_controller"] = controller.stop()
            except BaseException as error:
                report["cleanup_controller_error"] = type(error).__name__ + ": " + str(error)
                report["passed"] = False
        for label, fd in (("owner", owner_fd), ("business", child_fd)):
            if fd is not None:
                try:
                    report["cleanup_" + label + "_exited"] = pidfd_exited(fd, 20)
                    if not report["cleanup_" + label + "_exited"]:
                        report["passed"] = False
                except BaseException as error:
                    report["cleanup_" + label + "_error"] = type(error).__name__ + ": " + str(error)
                    report["passed"] = False
                finally:
                    try:
                        os.close(fd)
                    except BaseException as error:
                        report["cleanup_" + label + "_close_error"] = type(error).__name__ + ": " + str(error)
                        report["passed"] = False
        try:
            report["retained_file_receipts"] = [file_receipt(path) for path in sorted(root.rglob("*"))
                if path.is_file() and path.name not in ("case-report.json", "case-report.json.pending")]
        except BaseException as error:
            report["file_receipt_error"] = type(error).__name__ + ": " + str(error)
            report["passed"] = False
        report["finished_monotonic_ns"] = time.monotonic_ns()
        save(root / "case-report.json", report)


def main(args):
    need(sys.platform == "linux" and hasattr(os, "pidfd_open") and hasattr(signal, "pidfd_send_signal"),
         "Linux pidfd support required")
    os.umask(0o077)
    # Adopt only descendants of this new harness. This allows raw wait4 proof
    # for an SSH child orphaned by the deliberate controller SIGKILL.
    need(ctypes.CDLL(None, use_errno=True).prctl(36, 1, 0, 0, 0) == 0, "child subreaper unavailable")
    need(not own_child_pids(), "harness began with an unexpected child")
    out = args.out.absolute()
    need(out.parent == direct(DEV) and re.fullmatch(r"a[0-9]+-native-owner-[a-z0-9-]+", out.name)
         and not os.path.lexists(out), "fresh direct development child required")
    out.mkdir(mode=0o700)
    report = {"schema": "hepta-native-owner-recovery/v1", "passed": False, "cases": [], "errors": [],
              "scope": "qualified Rust MCP, direct SSH, original systemd owner, synthetic local effect",
              "not_covered": ["observation pool authentication", "target reboot", "physical power loss", "arbitrary external effects"],
              "automatic_retries": 0, "service_configuration_changes": 0,
              "planned_cases": list(CASES), "started_unix": time.time()}
    inputs = []
    try:
        q, bundle = qualification(direct(args.qualification), args.qualification_sha256)
        report["bundle"] = bundle
        binary = Path(bundle["binary"]["path"])
        inputs = [file_receipt(Path(__file__)), bundle["qualification"], bundle["binary"],
                  file_receipt(args.ssh_config), file_receipt(args.known_hosts)]
        report["inputs"] = inputs
        need(inputs[-2]["sha256"] == args.ssh_config_sha256 and inputs[-1]["sha256"] == args.known_hosts_sha256,
             "SSH admission files differ")
        validate_ssh_config(args.ssh_config)
        need(re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", args.ssh_target), "SSH alias required")
        wrapper_dir = out / "bin"
        wrapper_dir.mkdir(mode=0o700)
        options = {"BatchMode": "yes", "ConnectTimeout": "8", "ConnectionAttempts": "1",
                   "StrictHostKeyChecking": "yes", "ForwardAgent": "no", "ForwardX11": "no",
                   "ClearAllForwardings": "yes", "ControlMaster": "no", "ControlPath": "none",
                   "ControlPersist": "no", "PasswordAuthentication": "no", "KbdInteractiveAuthentication": "no",
                   "AddKeysToAgent": "no", "UpdateHostKeys": "no", "UserKnownHostsFile": str(direct(args.known_hosts)),
                   "GlobalKnownHostsFile": "/dev/null", "KnownHostsCommand": "none", "LocalCommand": "none",
                   "PermitLocalCommand": "no", "RequestTTY": "no"}
        command = ["/usr/bin/ssh", "-F", str(direct(args.ssh_config))]
        for name, value in options.items():
            command.extend(["-o", name + "=" + value])
        create(wrapper_dir / "ssh", ("#!/bin/sh\nexec " + " ".join(map(shlex.quote, command)) + ' "$@"\n').encode(), 0o700)
        probe_code = "import json,os,pathlib,socket;print(json.dumps({'uid':os.geteuid(),'hostname':socket.gethostname(),'boot_id':pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip()}))"
        probe = subprocess.run([*command, "-T", args.ssh_target, "python3 -I -S -c " + shlex.quote(probe_code)],
                               stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
        create(out / "ssh-preflight.stdout", probe.stdout)
        create(out / "ssh-preflight.stderr", probe.stderr)
        need(probe.returncode == 0, "direct SSH admission probe failed")
        host = json.loads(probe.stdout)
        need(host == {"uid": os.geteuid(), "hostname": socket.gethostname(),
                      "boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip()},
             "SSH alias is not this same Linux host/account")
        report["direct_ssh_preflight"] = host
        report["ssh_wrapper_sha256"] = file_receipt(wrapper_dir / "ssh")["sha256"]
        create(out / "frozen-plan.json", canonical({"cases": list(CASES), "inputs": inputs,
            "bundle": bundle, "ssh_target": args.ssh_target, "direct_ssh_preflight": host,
            "business_timeout_seconds": 90, "business_release_deadline_seconds": 75,
            "controller_workers": 2, "per_case_business_processes": 1,
            "pool_requested": False, "detached_fallback_allowed": False}))
        for name in CASES:
            row = {"name": name, "passed": False}
            report["cases"].append(row)
            save(out / "report.json", report)
            try:
                case(name, out / name, binary, wrapper_dir, args.ssh_target, row)
            except BaseException as error:
                row["error"] = type(error).__name__ + ": " + str(error)
                save(out / name / "case-report.json", row)
                raise
            save(out / "report.json", report)
        report["passed"] = len(report["cases"]) == len(CASES) and all(row["passed"] for row in report["cases"])
    except BaseException as error:
        report["errors"].append(type(error).__name__ + ": " + str(error))
        report["passed"] = False
    finally:
        try:
            for item in inputs:
                need(file_receipt(item["path"]) == item, "frozen input changed: " + item["path"])
            if "bundle" in report:
                source = Path(report["bundle"]["source"])
                actual = {str(p.relative_to(source)): file_receipt(p)["sha256"]
                          for p in sorted(source.rglob("*")) if p.is_file()}
                need(actual == report["bundle"]["source_map"], "qualified source changed")
            report["frozen_inputs_unchanged"] = True
        except BaseException as error:
            report["errors"].append("final fence: " + str(error))
            report["passed"] = False
        report["unexecuted_cases"] = [name for name in CASES if not any(row["name"] == name for row in report["cases"])]
        report["finished_unix"] = time.time()
        save(out / "report.json", report)
        print(json.dumps({"report": str(out / "report.json"), "passed": report["passed"],
                          "attempted_cases": len(report["cases"]), "errors": report["errors"]}), flush=True)
    return 0 if report["passed"] else 1


